interface DeliverySink {
 onFailure(reason: string): void
 onfailure(reason: string): void
}
export class CaseRelay {
 connect(engine: Engine, target: DeliverySink): void {
  engine.observe({ upper: (reason: string) => { target.onFailure(reason) }, lower: (reason: string) => { target.onfailure(reason) } })
 }
}
